import{c as n,Q as a,j as t,m as p}from"./chunks/framework.DOi4mjdC.js";const l="/assets/%E7%AE%97%E5%AD%90%E5%BC%80%E5%8F%91%E7%AB%AF%E5%88%B0%E7%AB%AF%E6%B5%81%E7%A8%8B-37.BAd_fXM9.png",e="/assets/%E7%BC%96%E8%AF%91%E8%BF%87%E7%A8%8B%E7%A4%BA%E6%84%8F%E5%9B%BE.CiRbW8IU.png",_=JSON.parse('{"title":"简易自定义算子工程","description":"","frontmatter":{},"headers":[{"level":1,"title":"简易自定义算子工程","slug":"简易自定义算子工程"},{"level":2,"title":"创建算子工程","slug":"创建算子工程"},{"level":2,"title":"算子实现","slug":"算子实现"},{"level":2,"title":"算子编译","slug":"算子编译"},{"level":2,"title":"算子调用","slug":"算子调用"}],"relativePath":"guide/编程指南/附录/简易自定义算子工程.md","filePath":"guide/编程指南/附录/简易自定义算子工程.md"}'),o={name:"guide/编程指南/附录/简易自定义算子工程.md"};function i(c,s,u,d,q,r){return a(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="简易自定义算子工程" tabindex="-1">简易自定义算子工程 <a class="header-anchor" href="#简易自定义算子工程" aria-label="Permalink to &quot;简易自定义算子工程&quot;">​</a></h1><p>本章节介绍的简易自定义算子工程，是上文中介绍的自定义算子工程的简化版，对算子的编译、打包、部署过程进行简化，便于开发者将该工程集成到自己的算子工程。</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p></p><ul><li>使用该工程，支持在如下平台进行自定义算子开发： <ul><li>Atlas A2训练系列产品</li><li>Atlas 推理系列产品</li></ul></li><li>使用本工程开发的算子，只支持通过单算子API执行（aclnn）方式进行调用。</li><li>本工程暂不支持算子的交叉编译功能。</li></ul></div><p>基于简易自定义算子工程的算子开发流程图如下：</p><p><img src="'+l+`" alt=""></p><h2 id="创建算子工程" tabindex="-1">创建算子工程 <a class="header-anchor" href="#创建算子工程" aria-label="Permalink to &quot;创建算子工程&quot;">​</a></h2><p>和<a href="./工程化算子开发/创建算子工程.html">创建算子工程</a>类似，简易自定义算子工程通过msOpGen生成，基于算子原型定义输出算子工程，包括<strong>算子host侧代码实现文件</strong>、<strong>算子kernel侧实现文件</strong>以及<strong>工程编译配置文件等</strong>。主要差异点在于：创建简易算子工程需要通过-f参数配置framework框架为aclnn。</p><p>使用msOpGen工具创建简易算子开发工程的步骤如下：</p><ol><li><p>编写算子的原型定义json文件，用于生成算子开发工程。</p><p>例如，AddCustom算子的json文件命名为add_custom.json，文件内容如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;op&quot;: &quot;AddCustom&quot;,</span></span>
<span class="line"><span>        &quot;input_desc&quot;: [</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;name&quot;: &quot;x&quot;,</span></span>
<span class="line"><span>                &quot;param_type&quot;: &quot;required&quot;,</span></span>
<span class="line"><span>                &quot;format&quot;: [</span></span>
<span class="line"><span>                    &quot;ND&quot;,</span></span>
<span class="line"><span>                    &quot;ND&quot;,</span></span>
<span class="line"><span>                    &quot;ND&quot;</span></span>
<span class="line"><span>                ],</span></span>
<span class="line"><span>                &quot;type&quot;: [</span></span>
<span class="line"><span>                    &quot;fp16&quot;,</span></span>
<span class="line"><span>                    &quot;float&quot;,</span></span>
<span class="line"><span>                    &quot;int32&quot;</span></span>
<span class="line"><span>                ]</span></span>
<span class="line"><span>            },</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;name&quot;: &quot;y&quot;,</span></span>
<span class="line"><span>                &quot;param_type&quot;: &quot;required&quot;,</span></span>
<span class="line"><span>                &quot;format&quot;: [</span></span>
<span class="line"><span>                    &quot;ND&quot;,</span></span>
<span class="line"><span>                    &quot;ND&quot;,</span></span>
<span class="line"><span>                    &quot;ND&quot;</span></span>
<span class="line"><span>                ],</span></span>
<span class="line"><span>                &quot;type&quot;: [</span></span>
<span class="line"><span>                    &quot;fp16&quot;,</span></span>
<span class="line"><span>                    &quot;float&quot;,</span></span>
<span class="line"><span>                    &quot;int32&quot;</span></span>
<span class="line"><span>                ]</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        ],</span></span>
<span class="line"><span>        &quot;output_desc&quot;: [</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;name&quot;: &quot;z&quot;,</span></span>
<span class="line"><span>                &quot;param_type&quot;: &quot;required&quot;,</span></span>
<span class="line"><span>                &quot;format&quot;: [</span></span>
<span class="line"><span>                    &quot;ND&quot;,</span></span>
<span class="line"><span>                    &quot;ND&quot;,</span></span>
<span class="line"><span>                    &quot;ND&quot;</span></span>
<span class="line"><span>                ],</span></span>
<span class="line"><span>                &quot;type&quot;: [</span></span>
<span class="line"><span>                    &quot;fp16&quot;,</span></span>
<span class="line"><span>                    &quot;float&quot;,</span></span>
<span class="line"><span>                    &quot;int32&quot;</span></span>
<span class="line"><span>                ]</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        ]</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>]</span></span></code></pre></div></li><li><p>使用msOpGen工具生成算子的开发工程。以生成AddCustom的算子工程为例，下文仅针对关键参数进行解释，详细参数说明请参见<a href="https://hiascend.com/document/redirect/CannCommercialToolOpDev" target="_blank" rel="noreferrer">《算子开发工具用户指南》</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>\${INSTALL_DIR}/python/site-packages/bin/msopgen gen -i $HOME/sample/add_custom.json -c ai_core-&lt;soc_version&gt; -lan cpp -out $HOME/sample/AddCustom -f aclnn</span></span></code></pre></div><ul><li><p>\${INSTALL_DIR}为CANN软件安装后文件存储路径，请根据实际环境进行替换。</p></li><li><p>-i：指定算子原型定义文件_add_custom_.json所在路径，请根据实际情况修改。</p></li><li><p>-c：<code>ai_core-_&lt;soc_version&gt;</code>代表算子在AI Core上执行，_&lt;soc_version&gt;_为昇腾AI处理器的型号。</p></li><li><p>-lan：参数cpp代表算子基于Ascend C编程框架，使用C/C++编程语言开发。</p></li><li><p>-out：生成文件所在路径，可配置为绝对路径或者相对路径，并且工具执行用户对路径具有可读写权限。若不配置，则默认生成在执行命令的当前路径。</p></li><li><p>-f：表示框架类型，aclnn表示生成简易工程。</p></li></ul></li><li><p>命令执行完后，会在-out指定目录或者默认路径下生成算子工程目录，工程中包含算子实现的模板文件，编译脚本等，以AddCustom算子为例，目录结构如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AddCustom</span></span>
<span class="line"><span>├── build.sh                        // 编译入口脚本</span></span>
<span class="line"><span>├── cmake </span></span>
<span class="line"><span>│   ├── config.cmake              // 编译配置项</span></span>
<span class="line"><span>│   ├── func.cmake</span></span>
<span class="line"><span>│   ├── intf.cmake</span></span>
<span class="line"><span>│   └── util                       // 算子工程编译所需脚本及公共编译文件存放目录</span></span>
<span class="line"><span>├── CMakeLists.txt                  // 算子工程的CMakeLists.txt</span></span>
<span class="line"><span>├── op_host                         // host侧实现文件</span></span>
<span class="line"><span>│   ├── add_custom_tiling.h     // 算子tiling定义文件</span></span>
<span class="line"><span>│   ├── add_custom.cpp          // 算子原型注册、tiling实现等内容文件</span></span>
<span class="line"><span>│   ├── CMakeLists.txt</span></span>
<span class="line"><span>├── op_kernel                       // kernel侧实现文件</span></span>
<span class="line"><span>│   ├── CMakeLists.txt   </span></span>
<span class="line"><span>│   ├── add_custom.cpp          // 算子代码实现文件</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>上述目录结构中的粗体文件为后续算子开发过程中需要修改的文件，其他文件无需修改。</p></div></li></ol><h2 id="算子实现" tabindex="-1">算子实现 <a class="header-anchor" href="#算子实现" aria-label="Permalink to &quot;算子实现&quot;">​</a></h2><p>参考<a href="./工程化算子开发/Kernel侧算子实现.html">Kernel侧算子实现</a>、<a href="./工程化算子开发/Host侧Tiling实现/基本流程.html">Host侧Tiling实现</a>、<a href="./工程化算子开发/算子原型定义.html">算子原型定义</a>完成算子实现。</p><h2 id="算子编译" tabindex="-1">算子编译 <a class="header-anchor" href="#算子编译" aria-label="Permalink to &quot;算子编译&quot;">​</a></h2><p>算子kernel侧和host侧实现开发完成后，需要对算子进行编译，生成算子静态库；自动生成aclnn调用实现代码和头文件，链接算子静态库生成aclnn动态库，以支持后续的单算子API执行方式（aclnn）的算子调用。编译过程如下：</p><ul><li>根据host侧算子实现文件自动生成aclnn接口aclnn_*.h和aclnn实现文件aclnn_.cpp。</li><li>编译Tiling实现和算子原型定义生成Tiling动态库liboptiling.so（libcust_opmaster_rt2.0）。</li><li>编译kernel侧算子实现文件，并加载Tiling动态库，生成kernel静态库libkernels.a。</li><li>编译aclnn实现文件，并链接kernel静态库libkernels.a生成单算子API调用的动态库libcust_opapi.so。</li></ul><p>上述编译过程示意图如下：</p><p><strong>图 1</strong> 编译过程示意图<br><img src="`+e+`" alt="" title="编译过程示意图"></p><p>上文描述的过程都封装在编译脚本中，开发者进行编译时参考如下的步骤进行操作：</p><ol><li><p>完成工程编译相关配置。</p><ul><li><p>修改cmake目录下config.cmake中的配置项，config.cmake文件内容如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set(CMAKE_CXX_FLAGS_DEBUG &quot;&quot;)</span></span>
<span class="line"><span>set(CMAKE_CXX_FLAGS_RELEASE &quot;&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if (NOT DEFINED CMAKE_BUILD_TYPE)</span></span>
<span class="line"><span>    set(CMAKE_BUILD_TYPE Release CACHE STRING &quot;&quot;)</span></span>
<span class="line"><span>endif()</span></span>
<span class="line"><span>if (CMAKE_INSTALL_PREFIX_INITIALIZED_TO_DEFAULT) </span></span>
<span class="line"><span>    set(CMAKE_INSTALL_PREFIX &quot;\${CMAKE_SOURCE_DIR}/build_out&quot; CACHE PATH &quot;&quot; FORCE)</span></span>
<span class="line"><span>endif()</span></span>
<span class="line"><span>if (NOT DEFINED ASCEND_CANN_PACKAGE_PATH)</span></span>
<span class="line"><span>    set(ASCEND_CANN_PACKAGE_PATH /usr/local/Ascend/cann CACHE PATH &quot;&quot;) //请替换为CANN软件包安装后的实际路径</span></span>
<span class="line"><span>endif()</span></span>
<span class="line"><span>if (NOT DEFINED ASCEND_PYTHON_EXECUTABLE)</span></span>
<span class="line"><span>    set(ASCEND_PYTHON_EXECUTABLE python3 CACHE STRING &quot;&quot;)</span></span>
<span class="line"><span>endif()</span></span>
<span class="line"><span>if (NOT DEFINED ASCEND_COMPUTE_UNIT)</span></span>
<span class="line"><span>    set(ASCEND_COMPUTE_UNIT ascendxxx CACHE STRING &quot;&quot;)</span></span>
<span class="line"><span>endif()</span></span>
<span class="line"><span>if (NOT DEFINED ENABLE_TEST)</span></span>
<span class="line"><span>    set(ENABLE_TEST FALSE CACHE BOOL &quot;&quot;)</span></span>
<span class="line"><span>endif()</span></span>
<span class="line"><span>if (NOT DEFINED ENABLE_CROSS_COMPILE)</span></span>
<span class="line"><span>    set(ENABLE_CROSS_COMPILE  FALSE CACHE BOOL &quot;&quot;)</span></span>
<span class="line"><span>endif()</span></span>
<span class="line"><span>if (NOT DEFINED CMAKE_CROSS_PLATFORM_COMPILER)</span></span>
<span class="line"><span>    set(CMAKE_CROSS_PLATFORM_COMPILER &quot;/your/cross/compiler/path&quot; CACHE PATH &quot;&quot;)</span></span>
<span class="line"><span>endif()</span></span>
<span class="line"><span>set(ASCEND_TENSOR_COMPILER_PATH \${ASCEND_CANN_PACKAGE_PATH}/compiler)</span></span>
<span class="line"><span>set(ASCEND_CCEC_COMPILER_PATH \${ASCEND_TENSOR_COMPILER_PATH}/ccec_compiler/bin)</span></span>
<span class="line"><span>set(ASCEND_AUTOGEN_PATH \${CMAKE_BINARY_DIR}/autogen)</span></span>
<span class="line"><span>file(MAKE_DIRECTORY \${ASCEND_AUTOGEN_PATH})</span></span>
<span class="line"><span>set(CUSTOM_COMPILE_OPTIONS &quot;custom_compile_options.ini&quot;)</span></span>
<span class="line"><span>execute_process(COMMAND rm -rf \${ASCEND_AUTOGEN_PATH}/\${CUSTOM_COMPILE_OPTIONS}</span></span>
<span class="line"><span>                COMMAND touch \${ASCEND_AUTOGEN_PATH}/\${CUSTOM_COMPILE_OPTIONS})</span></span></code></pre></div><p><strong>表 1</strong> 需要开发者配置的常用参数列表</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;31.4%&quot;&gt;&lt;p&gt;参数名称&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;38.7%&quot;&gt;&lt;p&gt;参数描述&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.9%&quot;&gt;&lt;p&gt;默认值&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;31.4%&quot;&gt;&lt;p&gt;ASCEND_CANN_PACKAGE_PATH&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;38.7%&quot;&gt;&lt;p&gt;CANN软件包安装路径，请根据实际情况进行修改。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.9%&quot;&gt;&lt;p&gt;“/usr/local/Ascend/cann”&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;31.4%&quot;&gt;&lt;p&gt;CMAKE_BUILD_TYPE&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;38.7%&quot;&gt;&lt;p&gt;编译模式选项，可配置为：&lt;/p&gt; &lt;ul&gt;&lt;li&gt;“Release”，Release版本，不包含调试信息，编译最终发布的版本。&lt;/li&gt;&lt;li&gt;“Debug”，“Debug”版本，包含调试信息，便于开发者开发和调试。&lt;/li&gt;&lt;/ul&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.9%&quot;&gt;&lt;p&gt;“Release”&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;31.4%&quot;&gt;&lt;p&gt;CMAKE_INSTALL_PREFIX&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;38.7%&quot;&gt;&lt;p&gt;编译产物存放的目录，不指定则为默认值。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.9%&quot;&gt;&lt;p&gt;\${CMAKE_SOURCE_DIR}/build_out：&lt;/p&gt; &lt;p&gt;算子工程目录下的build_out目录&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li><li><p>配置编译相关环境变量（可选）</p><p><strong>表 2</strong> 环境变量说明</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.54%&quot;&gt;&lt;p&gt;环境变量&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;70.46%&quot;&gt;&lt;p&gt;配置说明&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;29.54%&quot;&gt;&lt;p&gt;CMAKE_CXX_COMPILER_LAUNCHER&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;70.46%&quot;&gt;&lt;p&gt;用于配置C++语言编译器（如g++）、毕昇编译器的启动器程序为ccache，配置后即可开启cache缓存编译，&lt;span&gt;加速重复编译并提高构建效率&lt;/span&gt;。用法如下，在对应的CMakeLists.txt进行设置：&lt;/p&gt; &lt;pre class=&quot;screen&quot;&gt;set(CMAKE_CXX_COMPILER_LAUNCHER &lt;launcher_program&gt;)&lt;/pre&gt; &lt;p&gt;其中&lt;launcher_program&gt;是ccache的安装路径，比如ccache的安装路径为/usr/bin/ccache，示例如下：&lt;/p&gt; &lt;pre class=&quot;screen&quot;&gt;set(CMAKE_CXX_COMPILER_LAUNCHER /usr/bin/ccache)&lt;/pre&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li></ul></li><li><p>（可选）如果需要编译多个算子，在op_kernel目录下的CMakeLists.txt中增加要编译的算子。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> </span></span>
<span class="line"><span># set custom compile options</span></span>
<span class="line"><span>if (&quot;\${CMAKE_BUILD_TYPE}x&quot; STREQUAL &quot;Debugx&quot;)</span></span>
<span class="line"><span>    add_ops_compile_options(ALL OPTIONS -g -O0)</span></span>
<span class="line"><span>endif()</span></span>
<span class="line"><span>#多算子编译通过add_kernel_compile命令增加算子源码文件即可</span></span>
<span class="line"><span>add_kernel_compile(AddCustom \${CMAKE_CURRENT_SOURCE_DIR}/add_custom.cpp)</span></span>
<span class="line"><span>add_kernel_compile(SubCustom \${CMAKE_CURRENT_SOURCE_DIR}/sub_custom.cpp)</span></span>
<span class="line"><span>if(ENABLE_TEST AND EXISTS \${CMAKE_CURRENT_SOURCE_DIR}/testcases)</span></span>
<span class="line"><span>    add_subdirectory(testcases)</span></span>
<span class="line"><span>endif()</span></span></code></pre></div></li><li><p>（可选）在算子工程中，如果开发者想对算子kernel侧代码增加一些自定义的编译选项，可以参考<a href="./工程化算子开发/算子包编译/算子工程编译.html#section7321165972311">支持自定义编译选项</a>进行编译选项的定制。</p></li><li><p>在算子工程目录下执行如下命令，进行算子工程编译。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./build.sh</span></span></code></pre></div><p>编译成功后，会在CMAKE_INSTALL_PREFIX/op_api目录存放生成的aclnn头文件和lib库，每一个算子都会对应一个单独的头文件。具体目录结构如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>├── op_api</span></span>
<span class="line"><span>│   ├── include</span></span>
<span class="line"><span>│       ├── aclnn_optype1.h</span></span>
<span class="line"><span>│       └── aclnn_optype2.h</span></span>
<span class="line"><span>│       └── aclnn_optypexxx.h</span></span>
<span class="line"><span>│   ├── lib</span></span>
<span class="line"><span>│       ├── libcust_opapi.so</span></span></code></pre></div><p>对于lib目录下生成的库文件可通过msobjdump工具进一步解析得到kernel信息，具体操作参见<a href="./msobjdump工具.html">msobjdump工具</a>。</p></li></ol><h2 id="算子调用" tabindex="-1">算子调用 <a class="header-anchor" href="#算子调用" aria-label="Permalink to &quot;算子调用&quot;">​</a></h2><p>完成<a href="./工程化算子开发/单算子API调用.html">单算子API调用</a>。</p>`,20)])])}const E=n(o,[["render",i]]);export{_ as __pageData,E as default};
